<?php
namespace Modules\Ran\Services;use Illuminate\Support\Facades\DB;use Modules\Ran\Entities\{Purchase,SupplierPayment};use Modules\Ran\Integrations\{FinanceIntegrationService,SupplierIntegrationService};use Modules\Ran\Support\RanContext;
class SupplierPaymentService{public function __construct(private NumberSequenceService $numbers,private SupplierIntegrationService $suppliers,private FinanceIntegrationService $finance,private AuditService $audit){}public function create(array $d):SupplierPayment{return DB::transaction(function()use($d){$this->suppliers->find((int)$d['supplier_contact_id']);$purchase=!empty($d['purchase_id'])?Purchase::query()->lockForUpdate()->findOrFail($d['purchase_id']):null;if($purchase&&(int)$purchase->supplier_contact_id!==(int)$d['supplier_contact_id'])throw new \DomainException('Selected purchase does not belong to the selected supplier.');$p=SupplierPayment::create(array_merge(RanContext::scope(),$d,['payment_no'=>$this->numbers->next('supplier_payment'),'status'=>'posted']));$this->finance->postSupplierPayment($p);$this->suppliers->debit((int)$p->supplier_contact_id,(float)$p->amount,(string)$p->payment_date,"Ran Supplier Payment {$p->payment_no}");if($purchase){$paid=min((float)$purchase->total_amount,(float)$purchase->paid_amount+(float)$p->amount);$purchase->update(['paid_amount'=>$paid,'balance_amount'=>max(0,(float)$purchase->total_amount-$paid)]);}$this->audit->record('supplier_payment_posted',$p);return $p;});}}
